import json,gzip,urllib.request,urllib.parse,concurrent.futures,re,hashlib,pathlib,time
root=pathlib.Path(__file__).resolve().parent;routes=json.load(open(root/'routes.json'))
titles={'Hawaii':'Hawaiian_Islands','Rapa Nui':'Easter_Island','Canton/Kanton/Abararinga':'Kanton_Island','Canton/Kanton/Abariringa':'Kanton_Island','Rawaki/Phoenix':'Rawaki_Island','Manra/Sydney':'Manra_Island','Orona/Hull':'Orona_Atoll','Nikumaroro/Gardner':'Nikumaroro','Kiritimati/Christmas (Pacific)':'Kiritimati','Tabuaeran/Fanning':'Tabuaeran','Teraina/Washington':'Teraina','Caroline/Millennium':'Caroline_Island','Penrhyn/Tongareva':'Penrhyn_atoll','Swains/Olohega':'Swains_Island','Main Hawaiian Islands':'Hawaiian_Islands','Northwestern Hawaiian Islands':'Northwestern_Hawaiian_Islands','Midway':'Midway_Atoll','Johnston':'Johnston_Atoll','Banaba/Ocean Island':'Banaba','Macquarie':'Macquarie_Island','Chatham':'Chatham_Islands','Kermadec':'Kermadec_Islands','Auckland':'Auckland_Islands','Campbell':'Campbell_Island_group','Antipodes':'Antipodes_Islands','Snares':'Snares_Islands','Norfolk/Phillip/Nepean island group':'Norfolk_Island','Amsterdam and Saint-Paul':'Île_Amsterdam','Aru archipelago (including Tanahbesar/Wokam, Wamar, Kola, Kobroor, Maikoor, Koba, Trangan)':'Aru_Islands','Howland':'Howland_Island','Baker':'Baker_Island','Jarvis':'Jarvis_Island','Palmyra':'Palmyra_Atoll','Pitcairn':'Pitcairn_Island','Henderson':'Henderson_Island_(Pitcairn_Islands)','Ducie':'Ducie_Island','Oeno':'Oeno_Island','Malden':'Malden_Island','Starbuck':'Starbuck_Island','Vostok':'Vostok_Island','Flint':'Flint_Island','Nassau':'Nassau_(Cook_Islands)','Manuae':'Manuae_(Cook_Islands)','Birnie':'Birnie_Island','McKean':'McKean_Island','Enderbury':'Enderbury_Island'}
def f(x):
 name=x['name'];title=titles.get(name,name.replace(' ','_'));url='https://en.wikipedia.org/wiki/'+urllib.parse.quote(title,safe='_()');fn=hashlib.sha256(name.encode()).hexdigest()[:12]+'.html.gz'
 try:
  data=urllib.request.urlopen(urllib.request.Request(url,headers={'User-Agent':'WorldAtlas-geographic-source-review/1.0'}),timeout=45).read();text=data.decode();(root/fn).write_bytes(gzip.compress(data,mtime=0))
  decimal=re.search(r'<span class="geo-dec">(.*?)</span>',text);coord=re.findall(r'<span class="(?:latitude|longitude)">(.*?)</span>',text)[:2]
  out={'name':name,'title':title,'url':url,'status':200,'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),'path':fn,'license':'CC BY-SA 4.0; linked media separate','retrieved_on':'2026-10-02','geo_decimal_html':decimal.group(1) if decimal else None,'coordinate_html':coord};print(name,out['geo_decimal_html'] or coord,flush=True);return out
 except Exception as e:print(name,str(e),flush=True);return {'name':name,'title':title,'url':url,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(8) as ex:result=list(ex.map(f,routes))
(root/'gazetteers.json').write_text(json.dumps(result,separators=(',',':')))
